import taf.rfrl.common_resources.python.ssh_common_commands as common
import logging
import time
import re
from taf.transport.ssh import ssh
ssh = ssh()


__all__ = ["prepare_for_tti_trace_log_capturing",
           "start_tti_trace",
           "stop_tti_trace",
           "convert_tti_trace_to_csv",
           "combine_csv_files_to_one"
           ]

TTI_TRACE_LOG_PATH_BASE = "/var/eventsTrace"
TTI_TRACE_TOOL_PATH = "/opt/tools/ttiTrace"
csv_copy_log_path = "/tmp"
CONTAINER_ID_L2RT = ""
TTI_TRACE_TOOL_PATH_CONTAINER = "/opt/tools/ttiTrace"


def prepare_for_tti_trace_log_capturing(connection):
    """
    Description:
        Will clear the tti trace logs on ABIL master of folder TTI_TRACE_LOG_PATH_BASE
    :param connection: connection alias for ABIL master
    :return: No return value for this method

    """
    global TTI_TRACE_TOOL_PATH
    global CONTAINER_ID_L2RT
    TTI_TRACE_TOOL_PATH = _get_event_trace_tool_folder(connection=connection)
    cmd_clear_logs = "rm -rf {}".format(TTI_TRACE_LOG_PATH_BASE)
    ssh.execute(command=cmd_clear_logs, connection=connection)
    CONTAINER_ID_L2RT = _get_container_id_for_L2RT(connection=connection)
    logging.debug("CONTAINER_ID_L2RT:{}, connection:{}".format(CONTAINER_ID_L2RT, connection))


def start_tti_trace(connection):
    """
    Description: Start TTI trace log capturing on ABIL master,
    :param connection: connection alias for ABIL master
    :return: no return for this method
    """

    cmd_start_tti = "nohup lxc-attach -n {} -- {}/eventsCollect.sh>out.txt 2>&1 &".format(
        CONTAINER_ID_L2RT, TTI_TRACE_TOOL_PATH_CONTAINER)
    ssh.send_command(command=cmd_start_tti, connection=connection)
    logging.debug("Start TTI trace command: {}".format(cmd_start_tti))
    time.sleep(0.1)
    if common.is_process_exist(process_name="eventsCollect.sh", connection=connection):
        logging.info(
            "Started TTI trace log capturing on ABIL master for L2-PS successfully")
    else:
        raise Exception("Fail to start TTI trace, process is not found")


def stop_tti_trace(connection):
    """
    Description: kill the TTI trace process if found.
    :param connection: connection alias for ABIL master
    :return: No return for this keyword
    """
    common.kill_process_by_name(
        process_name='eventsCollect.sh',
        connection=connection,
        is_sudo_used_for_kill=False)


def rename_file_in_case_filename_is_incorrect(act_unzip_file_name, connection):
    """
    If file name end up with non-string or non-digital value. Need to rename
    L2TtiTrace_EventsSnapshot.bin.10. ==> L2TtiTrace_EventsSnapshot.bin.10
    :param act_unzip_file_name:
    :param connection:
    :return:
    """
    logging.debug("Check if file name need to be updated")
    act_unzip_file_name = act_unzip_file_name.strip()
    new_file_name = re.sub(pattern=r'[\W|\D]*$', repl='', string=act_unzip_file_name).strip()
    logging.debug("act_unzip_file_name:{},new_file_name:{}".format(act_unzip_file_name, new_file_name))
    if new_file_name != act_unzip_file_name:
        cmd_rename_file_name = "cd {}; mv {} {}".format(TTI_TRACE_LOG_PATH_BASE,
                                                        act_unzip_file_name, new_file_name)
        output = ssh.execute(command=cmd_rename_file_name, connection=connection)
        logging.debug("Unzipped file name is end up with non-string or non-digital which need to rename, "
                      "command: {}, output: {}".format(cmd_rename_file_name, output))
    return new_file_name


def convert_tti_trace_to_csv(connection):
    """
    Description: 1. Create the CSV log folder for storing the CSV files
                 2. Convert all TTI trace logs to csv
                 3. Remove the log files which are decoded successfully
    :param connection: connection alias for ABIL master
    :return: Will return the log path for storing TTI trace:
             Example output is: /var/eventsTrace/TTI_CSV_20190220123609
    """
    list_tti_files = common.get_file_names_under_directory(
        directory=TTI_TRACE_LOG_PATH_BASE,
        file_indicator='*.tar.gz',
        connection=connection)
    logging.debug("All tti files: {}".format(list_tti_files))
    csv_log_path = _generate_csv_log_folder(connection=connection)
    if len(list_tti_files) != 0:
        for file_name in list_tti_files:
            cmd_unzip_tti_file = "cd {}; tar -zvxf {}".format(
                TTI_TRACE_LOG_PATH_BASE, file_name)
            unzip_file_name = ssh.execute(
                command=cmd_unzip_tti_file,
                connection=connection).strip()
            logging.debug("Execute command:{}, output:{}".format(cmd_unzip_tti_file, unzip_file_name))
            tti_bin_file_name = rename_file_in_case_filename_is_incorrect(
                act_unzip_file_name=unzip_file_name, connection=connection)
            tti_decoder_file_path = _get_decoder_file_path(connection=connection)
            cmd_tti_decoder = "cd {}; {} {} {}/{}".format(
                TTI_TRACE_LOG_PATH_BASE, tti_decoder_file_path, tti_bin_file_name, csv_log_path, tti_bin_file_name)
            output_decode = ssh.execute(command=cmd_tti_decoder, connection=connection, timeout='600 s')
            logging.debug("Output message for decode command {} is {}".format(cmd_tti_decoder, output_decode))
            logging.info(
                "Converted file {} to csv, will clear the tti logs in case logs are too big".format(file_name))
            cmd_clear_tti_logs = "cd {};rm {};rm {}".format(TTI_TRACE_LOG_PATH_BASE, file_name, tti_bin_file_name)
            ssh.execute(command=cmd_clear_tti_logs, connection=connection, timeout='10 s')
        return csv_log_path
    else:
        raise Exception(
            "There is no TTI trace log found, convert operation stopped")


def combine_csv_files_to_one(csv_log_path, direction, connection):
    """
    Description: 1. Get the csv files with name sorted
                 2. Combine CSV files one by one based on file name sequence
                 3. Combined csv log name will share the same timestamp with the csv_log_path
    :param csv_log_path: log path for storing the converted csv files
    :param direction: value can only be ul or dl. Case is sensitive
    :param connection: connection alias for ABIL master
    :return: will return the file path for the combined csv file.
             Example output: /XXX/XXX/TA_Combine_ul_Full_20190225084328.csv
                        or   /XXX/XXX/TA_Combine_dl_Full_20190225084328.csv
    """
    list_csv_file_names = _get_sorted_csv_file_names(
        csv_log_path=csv_log_path, direction=direction, connection=connection)
    logging.debug("sorted csv file names:{}".format(list_csv_file_names))
    timestamp = csv_log_path.split('_')[-1]
    csv_file_name_full = "TA_Combine_{}_Full_{}.csv".format(
        direction, timestamp)
    csv_file_path_full = "{}/{}".format(csv_copy_log_path, csv_file_name_full)

    logging.info("Start to combine csv contents")
    for csv_file_name in list_csv_file_names:
        cmd_add_csv_content = "cd {};cat {} >>{}".format(
            csv_log_path, csv_file_name, csv_file_path_full)
        output_add_csv_content = ssh.execute(
            command=cmd_add_csv_content, connection=connection).strip()
        if len(output_add_csv_content) != 0:
            raise Exception(
                "Combine csv file for {} failed. Output message is {}".format(
                    csv_file_name, output_add_csv_content))
        else:
            logging.info("Combine csv file {} to {} successfully".format(csv_file_name, csv_file_name_full))
            continue
    logging.info(
        "All CSV files have been combined. File path after combine is ")
    return csv_file_path_full


def _get_sorted_csv_file_names(csv_log_path, direction, connection):
    """
    Description: Get csv file names with name sorted by log id
    :param csv_log_path: log path for storing the converted csv files
    :param direction: value can only be ul or dl. Case is sensitive
    :param connection: connection alias for ABIL master
    :return: return a list for csv names
    """
    list_csv_file_name = common.get_file_names_under_directory(
        directory=csv_log_path,
        file_indicator='*L2TtiTrace_EventsSnapshot.bin.[0-9]*{}.csv'.format(direction),
        connection=connection)
    if len(list_csv_file_name) != 0:
        dict_csv_file_names = {}
        for csv_log_name in list_csv_file_name:
            log_index = int(re.findall(r'EventsSnapshot.bin.([\d]*).', csv_log_name)[0])
            logging.debug("log_index:{}".format(log_index))
            dict_csv_file_names[log_index] = csv_log_name
        list_sorted_csv_file_names = _get_dict_value_sorted_by_key(
            dict_csv_file_names)
        return list_sorted_csv_file_names
    else:
        raise Exception(
            "There is no csv log found with {} direction under {}".format(
                direction, csv_log_path))


def _generate_csv_log_folder(connection):
    """
    Create csv log folder under /var/eventsTrace
    :param connection: connection alias for ABIL master
    :return: Will return the log path for storing TTI trace:
             Example output is: /var/eventsTrace/TTI_CSV_20190220123609
    """
    timestamp = ssh.execute(
        command="date +%Y%m%d%H%M%S",
        connection=connection).strip()
    csv_folder_name = "TTI_CSV_{}".format(timestamp)
    log_path = "{}/{}".format(TTI_TRACE_LOG_PATH_BASE, csv_folder_name)
    cmd_create_log_path = "cd {}; mkdir {}".format(
        TTI_TRACE_LOG_PATH_BASE, csv_folder_name)
    common.try_command(
        command=cmd_create_log_path,
        connection=connection,
        retry_time=10)
    logging.info("CSV log folder {} is created".format(log_path))
    return log_path


def _get_dict_value_sorted_by_key(input_dict):
    """
    Description: Sort a dictionary by key
    :param dict:
    :return: Return a list with dict values
    """
    dict_keys = sorted(input_dict.keys())
    list_dict_value = []
    for dict_key in dict_keys:
        list_dict_value.append(input_dict[dict_key])
    return list_dict_value


def _get_decoder_file_path(connection):
    """
    Description: Ding Binmei
    Get decoder file path, as decoder file path is different in different stream
    :param connection:
    :return:
    """
    possible_decoder_file_names = ['eventSnapshotDecoder', 'eventDecoder']
    file_names_under_tool_path = common.get_file_names_under_directory(
        directory=TTI_TRACE_TOOL_PATH, connection=connection, file_indicator='event*')
    logging.debug("File names under {}: {}".format(TTI_TRACE_TOOL_PATH, file_names_under_tool_path))
    decoder_file_path = ""
    for decoder_file_name in possible_decoder_file_names:
        if decoder_file_name in file_names_under_tool_path:
            decoder_file_path = TTI_TRACE_TOOL_PATH + "/" + decoder_file_name
            break
    if len(decoder_file_path) != 0:
        return decoder_file_path
    else:
        raise Exception("No decoder script found under {} on {}".format(TTI_TRACE_TOOL_PATH, connection))


def _get_event_trace_tool_folder(connection):
    """
    Ding Binmei: Adapt for ABIO blade.
    :param connection: If ABIO blade, connection should be ABIO master; Else should be on ABIL master or slave
    :return:
    """
    origin_tti_trace_tool_path = TTI_TRACE_TOOL_PATH
    is_tti_trace_tool_folder_exist = ssh.file_exists(remote_path=origin_tti_trace_tool_path, connection=connection)
    if is_tti_trace_tool_folder_exist is False:
        new_tti_trace_tool_path = "/tmp/node_L2RT20" + origin_tti_trace_tool_path
    else:
        new_tti_trace_tool_path = origin_tti_trace_tool_path
    return new_tti_trace_tool_path


def _get_container_id_for_L2RT(connection):
    """
    Ding Binmei: On 21A and trunk, event trace log capture need to be done on L2RT container,
    so change the method for log capturing
    :param connection:
    :return:
    """
    cmd_get_container_id_l2rt = "ls -l /tmp|grep ram/node_L2RT"
    output = ssh.execute(command=cmd_get_container_id_l2rt, connection=connection)
    pattern = re.compile(pattern=r'node_([\w|\d]*)')
    if pattern.findall(output):
        container_id = pattern.findall(output)[0]
    else:
        raise Exception("Fail to get container ID for L2RT on {}, output for command:{}, is: {}".format(
            connection, cmd_get_container_id_l2rt, output))
    return container_id
